def convert_posted_bonus(apps, schema_editor):
    """T-148 已自動入帳（posted_at 有值）的組，照「已結算」保留、金額不變（T-203 Q5，使用者 2026-11-17）。
    正式站 2026-11-17 查詢為 0 組；保留這段是為了上線前若有人建了規則並自動入帳。"""
    OrderVolumeBonus = apps.get_model("sales", "OrderVolumeBonus")
    VolumeBonusSettlement = apps.get_model("sales", "VolumeBonusSettlement")
    groups = {}
    for row in OrderVolumeBonus.objects.filter(posted_at__isnull=False).order_by("pk"):
        groups.setdefault((row.rule_id, row.period_id, row.dealer_id), []).append(row)
    for (rule_id, period_id, dealer_id), rows in groups.items():
        VolumeBonusSettlement.objects.create(
            rule_id=rule_id, period_id=period_id, dealer_id=dealer_id,
            quantity=len(rows), minimum_quantity=max(row.minimum_quantity for row in rows),
            bonus_per_vehicle=max(row.amount for row in rows), total_amount=sum(row.amount for row in rows),
            settled_at=min(row.posted_at for row in rows), settled_by="系統（T-148 自動入帳轉結算）",
        )


